import org.springframework.web.bind.annotation.RestController;

/**
 * The claim templates on a sheet, and claims added from them; a claim added from a template answers with the
 * person it belongs to. The signed-in user's name comes in the {@code X-User} header.
 */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimTemplateController {

    /** A template to save: a name (blank is refused), an amount with up to two decimals and a note. */
    public record TemplateForm(@Size(max = 1000) String name,
            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount, @Size(max = 500) String note) {
    }

    /** A template on the sheet; its amount with two decimals. */
    public record TemplateView(String name, String amount, String note) {

        static TemplateView of(ClaimTemplate t) {
            return new TemplateView(t.getName(), t.getAmount().setScale(2, RoundingMode.HALF_UP).toPlainString(),
                    t.getNote());
        }
    }

    /** The name of the template a claim is added from. */
    public record FromTemplateForm(@NotBlank @Size(max = 1000) String name) {
    }

    public record Refusal(String message) {
    }

    private final ClaimTemplates templates;
    private final ClaimService claims;
    private final PersonService people;
    private final RateService rates;
    private final StatementService statements;

    public ClaimTemplateController(ClaimTemplates templates, ClaimService claims, PersonService people,
            RateService rates, StatementService statements) {
        this.templates = templates;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.statements = statements;
    }

    @GetMapping("/claim-templates")
    public List<TemplateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return templates.list(sheetId.trim()).stream().map(TemplateView::of).toList();
    }

    /** Save a template, replacing the one of its name; answers with every template on the sheet. */
    @PostMapping("/claim-templates")
    public List<TemplateView> save(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody TemplateForm form) {
        String sheet = sheetId.trim();
        templates.save(sheet, user.trim(), form.name(), new BigDecimal(form.amount()), form.note());
        return list(sheet);
    }

    /** Add a DRAFT claim for a person from a template, by the claim form's rules. */
    @PostMapping("/people/{personId}/claims/from-template")
    public PersonView addClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody FromTemplateForm form) {
        String sheet = sheetId.trim();
        long id = templates.addClaim(sheet, user.trim(), personId, form.name());
        Person person = people.get(sheet, id);
        return PersonView.of(person, claims.forPerson(sheet, id), rates.table(sheet),
                statements.forPerson(sheet, id), people.patrons(sheet, id), people.clashing(sheet, person));
    }

    @ExceptionHandler(ClaimTemplateRefused.class)
    public ResponseEntity<Refusal> refused(ClaimTemplateRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** A claim due by a date inside a closed period: refused, nothing changed. */
    @ExceptionHandler(ClosedPeriodRefused.class)
    public ResponseEntity<Refusal> closed(ClosedPeriodRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another user saved a new template of the same name at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void taken() {
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The claim templates on a sheet, sorted by name; saving a name again replaces that template. A claim added from a
 * template is a DRAFT taking the template's amount and note at that moment, dated as a claim with no date, by every
 * rule of the claim form; changing the template later leaves the claims made from it as they are.
 */
@Service
public class ClaimTemplates {

    /** The longest a template's name may be. */
    static final int NAME_MAX = 100;

    private final ClaimTemplateRepository templates;
    private final ClaimService claims;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ApplicationEventPublisher events;

    public ClaimTemplates(ClaimTemplateRepository templates, ClaimService claims, SheetService sheets,
            SheetRepository sheetRows, ApplicationEventPublisher events) {
        this.templates = templates;
        this.claims = claims;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.events = events;
    }

    /** The templates on the sheet, sorted by name. */
    @Transactional(readOnly = true)
    public List<ClaimTemplate> list(String sheetId) {
        return templates.findBySheetIdOrderByNameAsc(sheetId);
    }

    /**
     * Save a template under its name, trimmed, replacing the one of that name; refused when the name is blank or
     * too long. The amount is one the claim form takes for a claim that corrects nothing.
     */
    @Transactional
    public void save(String sheetId, String user, String text, BigDecimal amount, String note) {
        String name = text == null ? "" : text.strip();
        if (name.isEmpty()) {
            throw new ClaimTemplateRefused("Enter a name for the template.");
        }
        if (name.length() > NAME_MAX) {
            throw new ClaimTemplateRefused("The template's name is too long.");
        }
        String kept = note == null ? "" : note;
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, name).orElse(null);
        if (template == null) {
            templates.saveAndFlush(new ClaimTemplate(sheetId, name, amount, kept));
        } else {
            template.setAmount(amount);
            template.setNote(kept);
            templates.flush();
        }
        events.publishEvent(new TemplateSaved(sheetId, user, name, amount, kept));
    }

    /** Add a DRAFT claim for the person with the named template's amount and note now. Returns the person. */
    @Transactional
    public long addClaim(String sheetId, String user, long personId, String name) {
        ClaimTemplate template = templates.findBySheetIdAndName(sheetId, name == null ? "" : name.strip())
                .orElseThrow(() -> new ClaimTemplateRefused("No such template on this sheet."));
        return claims.add(sheetId, user, personId, template.getAmount(), null, template.getNote());
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/** A claim template on a sheet: a name, on the sheet at most once, with the amount and note a claim is added with. */
@Entity
@Table(name = "sheet_claim_template")
public class ClaimTemplate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "note", nullable = false)
    private String note;

    protected ClaimTemplate() {
    }

    public ClaimTemplate(String sheetId, String name, BigDecimal amount, String note) {
        this.sheetId = sheetId;
        this.name = name;
        this.amount = amount;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }
}
