    e.preventDefault();
    if (this.busy) return;
    this.error.set('');
    this.busy = true;
    try {
      const refusal = await this.list.add(this.personId(), this.amount(), this.start(), this.every(), this.end());
      if (refusal) {
        this.error.set(refusal);
      } else {
        this.amount.set('');
        this.start.set('');
        this.every.set('');
        this.end.set('');
      }
    } finally {
      this.busy = false;
    }
  }
}
